import{_ as s,b as t,c as a,g as l}from"./chunks/framework.86O3EbG5.js";const c=JSON.parse('{"title":"启动的第一个Python项目","description":"","frontmatter":{"title":"启动的第一个Python项目","author":"oasis","date":"2022-12-04T00:00:00.000Z"},"headers":[],"relativePath":"articles/github/1.md","filePath":"articles/github/1.md"}'),e={name:"articles/github/1.md"};function n(p,i,h,o,r,k){return t(),a("div",null,[...i[0]||(i[0]=[l(`<ol><li>安装 python 3.9，在 mac 上用 brew install python</li><li>python 项目通过一个名字为 <code>requirements.txt</code> 的文件记录项目中的依赖包。</li><li>python 的项目依赖的包可以使用 <code>pip</code> 进行安装，<code>pip install</code></li><li>pip 可能提示不存在，因为没有加载 PATH 中。而且 Python 的不同版本的可执行文件名是不一致的，我通过 brew install python 后，python 的版本是 3.9,可执行文件名字是 python3</li><li>如果要在终端通过 python 处理文件，需要设置 alias</li></ol><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-light vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#D73A49;">alias</span><span style="--shiki-light:#24292E;--shiki-dark:#24292E;"> python</span><span style="--shiki-light:#D73A49;--shiki-dark:#D73A49;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#24292E;">/usr/bin/python3</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#D73A49;">alias</span><span style="--shiki-light:#24292E;--shiki-dark:#24292E;"> pip</span><span style="--shiki-light:#D73A49;--shiki-dark:#D73A49;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#24292E;">/usr/bin/pip3</span></span></code></pre></div><ol start="6"><li>pip 可以安装可执行文件的包，安装路径是在 sites_packages 的目录中有一份源代码，在 bin 目录中是可执行文件。</li><li>如果要执行通过 pip 安装的可执行文件，需要将它加入 PATH 中</li></ol><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-light vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#D73A49;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#24292E;"> PATH</span><span style="--shiki-light:#D73A49;--shiki-dark:#D73A49;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#032F62;">&quot;/Users/oasis/Library/Python/3.9/bin:</span><span style="--shiki-light:#24292E;--shiki-dark:#24292E;">$PATH</span><span style="--shiki-light:#032F62;--shiki-dark:#032F62;">&quot;</span></span></code></pre></div><p>概念解释：</p><ol><li><p>site-packages: 此目录是存放 python 依赖的目录，位于 python 安装路径中</p></li><li><p>相关链接：</p><ol><li><a href="https://docs.python.org/zh-cn/3.9/install/#how-installation-works" target="_blank" rel="noreferrer">https://docs.python.org/zh-cn/3.9/install/#how-installation-works</a></li><li><a href="https://phoenixnap.com/kb/linux-add-to-path" target="_blank" rel="noreferrer">https://phoenixnap.com/kb/linux-add-to-path</a></li><li><a href="https://seisman.github.io/how-to-write-makefile/" target="_blank" rel="noreferrer">https://seisman.github.io/how-to-write-makefile/</a></li></ol></li></ol>`,6)])])}const g=s(e,[["render",n]]);export{c as __pageData,g as default};
